parameters.query:
SELECT challenge_id, delivery_email, one_time_code, challenge_expires_at, proposal_id, proposal_version, payload_hash, proposal_payload, proposal_expires_at
FROM scopeledger.request_client_decision_challenge(
  $1::uuid,
  $2::text
);

parameters.responseBody:
={{ JSON.stringify({
  status: 'verification_required',
  challenge_id: $('Create Client Challenge').first().json.challenge_id,
  proposal_id: $('Create Client Challenge').first().json.proposal_id,
  proposal_version: $('Create Client Challenge').first().json.proposal_version,
  payload_hash: $('Create Client Challenge').first().json.payload_hash,
  proposal_expires_at: $('Create Client Challenge').first().json.proposal_expires_at,
  challenge_expires_at: $('Create Client Challenge').first().json.challenge_expires_at
}) }}
